SELECT ?sensor ?tsid WHERE {
  ?zone a brick:Zone; brick:hasName "Perimeter_bot_ZN_4".
  ?sensor brick:isAttachedTo ?zone.
  ?sensor ref:hasTimeseriesId ?tsid.
}

SELECT ?s ?class ?name WHERE {
  ?s a ?class.
  FILTER(str(?class) LCONTAINS "Zone")
  ?s brick:hasName ?name.
  FILTER(str(?name) LCONTAINS "Perimeter")
} LIMIT 30

SELECT ?s ?class ?name WHERE {
  ?s brick:hasName ?name.
  FILTER(CONTAINS(str(?name), "ZN_4"))
  ?s a ?class.
} LIMIT 40

SELECT ?s ?name WHERE {
  ?s a brick:Room.
  ?s brick:hasName ?name.
} LIMIT 40

